const chartCache=new Map(),chartPending=new Set(),chartErrors=new Map();
const chartSettings={period:'4h',ema200:true,ema360:true,news:true};
function chartKey(pid){return pid+':'+chartSettings.period}
async function fetchChart(pid,force=false){const key=chartKey(pid),period=chartSettings.period;if(chartPending.has(key))return;const previous=chartCache.get(key);if(!force&&previous&&Date.now()-previous.fetchedAt<60000)return;if(!force&&chartErrors.has(key)&&Date.now()-chartErrors.get(key).at<60000)return;chartPending.add(key);try{const r=await fetch('/api/chart?project='+encodeURIComponent(pid)+'&period='+period);const d=await r.json();if(!r.ok)throw Error(d.error);chartCache.set(key,d);chartErrors.delete(key)}catch(e){chartErrors.set(key,{message:e.message,at:Date.now()})}finally{chartPending.delete(key);if(state.project===pid&&chartSettings.period===period)render()}}
function linkedChart(p){
 const key=chartKey(p.id),d=chartCache.get(key),error=chartErrors.get(key),m=liveData?.markets[p.id];
 return `<section class="project-section linked-chart"><div class="project-section-title"><h3>价格与项目动态</h3><span>Binance ${escapeHtml(p.symbol)}USDT 永续</span></div><div class="chart-controls"><label>周期 <select id="chart-period">${['15m','1h','4h','1d'].map(v=>`<option ${chartSettings.period===v?'selected':''}>${v}</option>`).join('')}</select></label>${[['ema200','EMA 200'],['ema360','EMA 360'],['news','新闻标记']].map(([id,label])=>`<label><input type="checkbox" data-chart-toggle="${id}" ${chartSettings[id]?'checked':''}>${label}</label>`).join('')}<button data-chart-refresh>刷新图表</button></div><div class="chart-price">${m?.price?'$'+number(m.price):'—'} <small>${pct(m?.change24h)} / 24h</small></div>${error?`<p class="chart-error" role="status">${escapeHtml(error.message)}${d?'；下方保留上次成功数据':''}</p>`:''}${d?renderLinkedSvg(d,p):'<p class="module-empty" role="status">'+(error?'暂无可用图表':'正在获取 '+chartSettings.period+' K 线…')+'</p>'}<div class="chart-meta">${d?'仅已收盘 K 线 · 获取于 '+formatTime(d.fetchedAt)+' · 计算样本 '+d.warmupCount+' 根':'图表不使用模拟数据'}<br>新闻标记按来源发布时间定位；未取得精确时间的消息不打点。时间先后不代表因果关系。</div></section>`;
}
function renderLinkedSvg(d,p){
 const rows=d.candles.slice(-80);if(!rows.length)return '<p class="module-empty">暂无已收盘 K 线</p>';
 const values=rows.flatMap(r=>[r.low,r.high,...(chartSettings.ema200&&r.ema200!=null?[r.ema200]:[]),...(chartSettings.ema360&&r.ema360!=null?[r.ema360]:[])]);const lo=Math.min(...values),hi=Math.max(...values),pad=(hi-lo)*.08||1,min=lo-pad,max=hi+pad,W=900,H=330,left=12,right=94,top=15,bottom=68,step=(W-left-right)/rows.length;const x=i=>left+step*(i+.5),y=v=>top+(max-v)/(max-min)*(H-top-bottom);
 let content='';for(let i=0;i<5;i++){const v=min+(max-min)*i/4;content+=`<line x1="${left}" x2="${W-right}" y1="${y(v)}" y2="${y(v)}" stroke="#e5eae7"/><text x="${W-right+8}" y="${y(v)+4}" fill="#7a858c" font-size="12">${number(v)}</text>`}
 content+=rows.map((r,i)=>{const c=r.close>=r.open?'#38846b':'#bc6b65';return `<g><title>${formatTime(r.time)} 开 ${number(r.open)} 高 ${number(r.high)} 低 ${number(r.low)} 收 ${number(r.close)}</title><line x1="${x(i)}" x2="${x(i)}" y1="${y(r.high)}" y2="${y(r.low)}" stroke="${c}"/><rect x="${x(i)-step*.29}" y="${Math.min(y(r.open),y(r.close))}" width="${step*.58}" height="${Math.max(1,Math.abs(y(r.open)-y(r.close)))}" fill="${c}"/></g>`}).join('');
 for(const [field,color] of [['ema200','#b88b36'],['ema360','#7770ac']])if(chartSettings[field]){const points=rows.map((r,i)=>r[field]==null?null:`${x(i)},${y(r[field])}`).filter(Boolean);if(points.length)content+=`<polyline points="${points.join(' ')}" fill="none" stroke="${color}" stroke-width="1.6"><title>${field.toUpperCase()}</title></polyline>`}
 const start=rows[0].time,end=rows.at(-1).closeTime;const items=events.filter(e=>(e.projectIds||[e.p]).includes(p.id)&&!e.lowInformation&&e.type==='news'&&e.datePrecision!=='day'&&e.publishedAt>=start&&e.publishedAt<=end);const buckets=new Map();
 if(chartSettings.news)for(const e of items){const index=rows.findIndex(r=>e.publishedAt>=r.time&&e.publishedAt<=r.closeTime);if(index<0)continue;if(!buckets.has(index))buckets.set(index,[]);buckets.get(index).push(e)}
 for(const [i,items] of buckets){content+=`<g role="button" tabindex="0" class="chart-news-marker" data-chart-news="${i}" aria-label="查看 ${formatTime(rows[i].time)} 附近 ${items.length} 条新闻"><title>${escapeHtml(items.slice(0,3).map(e=>e.titleZh||e.title).join(" · "))} · 点击定位</title><circle cx="${x(i)}" cy="${H-42-(i%2)*20}" r="9" fill="#225b49"/><text x="${x(i)}" y="${H-38-(i%2)*20}" text-anchor="middle" fill="white" font-size="10">${items.length}</text></g>`}
 content+=`<text x="12" y="${H-13}" font-size="12" fill="#7a858c">${formatTime(start)}</text><text x="${W-right}" y="${H-13}" text-anchor="end" font-size="12" fill="#7a858c">${formatTime(end)}</text>`;
 const last=rows.at(-1);return `<svg class="candles" viewBox="0 0 ${W} ${H}" role="group" aria-label="${escapeHtml(p.symbol)} ${d.period} K 线与新闻时间标记">${content}</svg><div class="chart-legend"><span style="color:#b88b36">EMA 200：${number(last.ema200)}</span><span style="color:#7770ac">EMA 360：${number(last.ema360)}</span><span>${buckets.size} 个新闻时间点</span></div>${d.warmupCount<360?'<p class="module-note">历史样本不足 360 根，EMA 360 暂不可用。</p>':''}`;
}
function openChartNews(index){const p=catalog.find(p=>p.id===state.project),d=chartCache.get(chartKey(p.id)),r=d.candles.slice(-80)[index];const items=events.filter(e=>(e.projectIds||[e.p]).includes(p.id)&&!e.lowInformation&&e.type==='news'&&e.datePrecision!=='day'&&e.publishedAt>=r.time&&e.publishedAt<=r.closeTime);showForm(`${formTitle('这一时段的项目动态')}<p>${escapeHtml(formatTime(r.time))} — ${escapeHtml(formatTime(r.closeTime))}</p>${items.map(e=>`<button class="chart-news-item" data-chart-open="${e.id}"><small>${escapeHtml(e.source)} · ${formatTime(e.publishedAt)}</small><strong>${escapeHtml(e.titleZh||'中文译文生成中，点击查看来源')}</strong></button>`).join('')}`)}
const beforeLinkedChartRender=render;
render=function(){beforeLinkedChartRender();const p=catalog.find(p=>p.id===state.project);if(!p)return;const panel=$('#project-overview > .project-section');if(panel)panel.outerHTML=linkedChart(p);fetchChart(p.id)};
document.addEventListener('change',e=>{if(e.target.id==='chart-period'){chartSettings.period=e.target.value;render()}if(e.target.dataset.chartToggle){chartSettings[e.target.dataset.chartToggle]=e.target.checked;render()}});
document.addEventListener('click',e=>{const marker=e.target.closest('[data-chart-news]');if(marker){openChartNews(Number(marker.dataset.chartNews));return}const b=e.target.closest('button');if(!b)return;if(b.dataset.chartRefresh!==undefined)fetchChart(state.project,true);if(b.dataset.chartOpen){$('#form-dialog').close();openDetail(Number(b.dataset.chartOpen))}});
document.addEventListener('keydown',e=>{const marker=e.target.closest('[data-chart-news]');if(marker&&['Enter',' '].includes(e.key)){e.preventDefault();openChartNews(Number(marker.dataset.chartNews))}});
render();
